import { Injectable } from '@nestjs/common';
import { InjectDataSource } from '@nestjs/typeorm';
import { DataSource } from 'typeorm';
import * as fs from 'fs';

@Injectable()
export class DatabaseDumpService {
  constructor(
    @InjectDataSource() private readonly dataSource: DataSource,
  ) {}

  async dumpSqliteToSqlFile(destinationPath: string): Promise<void> {
    try {
      let sqlDumpText = '';

      // Header
      sqlDumpText +=
        '-- SQLite database dump generated by DatabaseDumpService\n' +
        'PRAGMA foreign_keys=OFF;\n' +
        'BEGIN TRANSACTION;\n\n';
  
      // 1. Fetch user-defined tables (exclude internal SQLite tables)
      const tables: Array<{ name: string; sql: string }> =
        await this.dataSource.query(`
          SELECT name, sql 
          FROM sqlite_master 
          WHERE type = 'table' 
            AND name NOT LIKE 'sqlite_%'
          ORDER BY name;
        `);

      // 2. Emit CREATE TABLE statements
      for (const table of tables) {
        const { name: tableName, sql } = table;
        if (!sql) continue; // skip views or weird entries without SQL
        sqlDumpText += `--\n-- Table structure for table \`${tableName}\`\n--\n\n`;
        sqlDumpText += `${sql};\n\n`;
      }

      // 3. Emit INSERT statements for each table
      for (const table of tables) {
        const tableName = table.name;

        const rows: any[] = await this.dataSource.query(
          `SELECT * FROM "${tableName}";`,
        );

        if (!rows.length) {
          // no data to dump
          continue;
        }

        sqlDumpText += `--\n-- Dumping data for table \`${tableName}\`\n--\n\n`;

        // OPTIONAL: MySQL‑style wrappers (can be removed if you only target SQLite)
        sqlDumpText += `LOCK TABLES \`${tableName}\` WRITE;\n`;
        sqlDumpText += `/*!40000 ALTER TABLE \`${tableName}\` DISABLE KEYS */;\n`;

        // We can either:
        //   a) create one big INSERT with multiple value tuples
        //   b) create one INSERT per row
        //
        // Here: one big INSERT (closer to what you already have)
        const columns = Object.keys(rows[0]);

        sqlDumpText += `INSERT INTO \`${tableName}\` (${columns
          .map((c) => `\`${c}\``)
          .join(', ')}) VALUES\n`;

        const rowStrings = rows.map((row) => {
          const values = columns.map((col) => {
            const val = row[col];

            if (val === null || val === undefined) return 'NULL';
            if (typeof val === 'number') return val.toString();

            // Handle dates or buffers if needed; here we treat everything else as text
            const escapedStr = String(val).replace(/'/g, "''");
            return `'${escapedStr}'`;
          });

          return `  (${values.join(', ')})`;
        });

        sqlDumpText += rowStrings.join(',\n') + ';\n';

        sqlDumpText += `/*!40000 ALTER TABLE \`${tableName}\` ENABLE KEYS */;\n`;
        sqlDumpText += `UNLOCK TABLES;\n\n`;
      }

      sqlDumpText += 'COMMIT;\n';
      sqlDumpText += 'PRAGMA foreign_keys=ON;\n';

      // 4. Ensure directory exists and write file
      const cleanPath = destinationPath.replace(/\\/g, '/');
      const lastSlashIdx = cleanPath.lastIndexOf('/');
      if (lastSlashIdx !== -1) {
        const dir = cleanPath.substring(0, lastSlashIdx);
        if (dir && !fs.existsSync(dir)) {
          fs.mkdirSync(dir, { recursive: true });
        }
      }

      fs.writeFileSync(destinationPath, sqlDumpText, 'utf8');
      console.log(`SQLite SQL dump generated at: ${destinationPath}`);
    } catch (error) {
      console.error('Failed to generate .sql dump file:', error);
      throw error;
    }
  }
}